test.query:
SELECT cramersVMerge(s) OVER (PARTITION BY p)
FROM
(
    SELECT p, cramersVState(a, b) OVER (PARTITION BY p ORDER BY number ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS s
    FROM (SELECT number, number % 10 AS p, intDiv(number, 10) % 30 AS a, intDiv(number, 70) % 30 AS b FROM numbers(10_000))
) FORMAT NULL;

SELECT theilsUMerge(s) OVER (PARTITION BY p)
FROM
(
    SELECT p, theilsUState(a, b) OVER (PARTITION BY p ORDER BY number ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS s
    FROM (SELECT number, number % 10 AS p, intDiv(number, 10) % 30 AS a, intDiv(number, 70) % 30 AS b FROM numbers(10_000))
) FORMAT NULL;
